package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import com.fasterxml.jackson.databind.util.ClassUtil;
import com.fasterxml.jackson.databind.util.LRUMap;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.Properties;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TypeFactory_constructMapType_TriageGen2Test {

    private TypeFactory typeFactory;

    @Before
    public void setUp() {
        typeFactory = TypeFactory.defaultInstance();
    }

    /**
     * Tests the branch where mapClass is Properties.class.
     * In this case, the key and value types should both be forced to String.
     */
    @Test
    public void testConstructMapType_Properties() {
        // Properties.class is a Map, but it's a special case where keys/values are always Strings
        // We pass Integer/Double as arguments to ensure the logic ignores them and uses String
        MapType result = typeFactory.constructMapType(Properties.class, Integer.class, Double.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(Properties.class, result.getRawClass());

        // Verify that both key and value types are String types
        Assert.assertEquals(String.class, result.getKeyType().getRawClass());
        Assert.assertEquals(String.class, result.getValueType().getRawClass());
    }

    /**
     * Tests the branch where mapClass is NOT Properties.class.
     * This exercises the _fromClass logic for both keyClass and valueClass.
     */
    @Test
    public void testConstructMapType_StandardMap() {
        Class<? extends Map> mapClass = HashMap.class;
        Class<?> keyClass = Integer.class;
        Class<?> valueClass = String.class;

        MapType result = typeFactory.constructMapType(mapClass, keyClass, valueClass);

        Assert.assertNotNull(result);
        Assert.assertEquals(mapClass, result.getRawClass());
        Assert.assertEquals(keyClass, result.getKeyType().getRawClass());
        Assert.assertEquals(valueClass, result.getValueType().getRawClass());
    }

    /**
     * Tests with different Map implementations and types to ensure generic handling.
     */
    @Test
    public void testConstructMapType_OtherMapImplementation() {
        // Testing with TreeMap and different types
        MapType result = typeFactory.constructMapType(java.util.TreeMap.class, String.class, Boolean.class);

        Assert.assertNotNull(result);
        Assert.assertEquals(java.util.TreeMap.class, result.getRawClass());
        Assert.assertEquals(String.class, result.getKeyType().getRawClass());
        Assert.assertEquals(Boolean.class, result.getValueType().getRawClass());
    }

    /**
     * Tests the edge case where key or value might be a primitive wrapper.
     */
    @Test
    public void testConstructMapType_Primitives() {
        MapType result = typeFactory.constructMapType(HashMap.class, long.class, double.class);

        Assert.assertNotNull(result);
        // Jackson's _fromClass handles primitive classes by mapping them to their wrapper types or specific JavaTypes
        Assert.assertEquals(long.class, result.getKeyType().getRawClass());
        Assert.assertEquals(double.class, result.getValueType().getRawClass());
    }
}
